    # Global Date & Category Filters
    st.subheader("⚙️ Global Filters")

    min_date = working_df["date"].min().date() if not working_df.empty else datetime.now().date()
    max_date = working_df["date"].max().date() if not working_df.empty else datetime.now().date()

    date_range = st.date_input(
        "Date Range",
        value=(min_date, max_date),
        min_value=min_date,
        max_value=max_date
    )

    all_categories = sorted(working_df["category"].dropna().unique().tolist())
    selected_categories = st.multiselect("Filter Categories", all_categories, default=all_categories)

    tx_types = ["All", "Debit (Expense)", "Credit (Income)"]
    selected_type = st.selectbox("Transaction Type", tx_types, index=0)

    # Apply global filtering
    if isinstance(date_range, tuple) and len(date_range) == 2:
        start_d, end_d = date_range
        filtered_df = working_df[
            (working_df["date"].dt.date >= start_d) &
            (working_df["date"].dt.date <= end_d)
        ]
    else:
        filtered_df = working_df.copy()

    if selected_categories:
        filtered_df = filtered_df[filtered_df["category"].isin(selected_categories)]

    if selected_type == "Debit (Expense)":
        filtered_df = filtered_df[filtered_df["transaction_type"].str.lower() == "debit"]
    elif selected_type == "Credit (Income)":
        filtered_df = filtered_df[filtered_df["transaction_type"].str.lower() == "credit"]

    st.markdown("---")

    st.caption(f"📁 **Source:** {st.session_state.data_source_name}")
    st.caption(f"📊 **Transactions Active:** {len(filtered_df):,} of {len(working_df):,}")

    if st.button("🔄 Reset to Default Sample Data", use_container_width=True):
        st.session_state.custom_df = None
        st.session_state.data_source_name = "Default Synthetic UPI Dataset (5,000 Transactions)"
        st.cache_data.clear()
        st.rerun()


