# ------------------------------------------------------------------------------
# MODULE 1: 📊 FINANCIAL DASHBOARD & EDA
# ------------------------------------------------------------------------------
if selected_menu == "📊 Financial Dashboard":
    st.markdown("## 📊 Financial Overview & Spending Behaviour")
    st.markdown(
        '<div class="section-note">'
        'Comprehensive visibility into your UPI cashflow, categorical distribution, and transaction patterns.'
        '</div>',
        unsafe_allow_html=True
    )

    # Core Financial Calculations
    income_sub = filtered_df[filtered_df["transaction_type"].str.lower() == "credit"]
    expense_sub = filtered_df[filtered_df["transaction_type"].str.lower() == "debit"]

    total_income = float(income_sub["amount"].sum())
    total_expenses = float(expense_sub["amount"].sum())
    net_savings = total_income - total_expenses
    savings_rate = (net_savings / total_income * 100) if total_income > 0 else 0.0

    if "balance_after_transaction" in working_df.columns:
        latest_bal = float(working_df.sort_values(["date", "time"]).iloc[-1]["balance_after_transaction"])
    else:
        latest_bal = 35000.0

    # Dynamic Safe-to-Spend
    safe_calc = data_engine.calculate_safe_to_spend_data(working_df)
    safe_amount = float(safe_calc["safe_to_spend"].iloc[0])
    daily_safe = float(safe_calc["daily_safe_spending"].iloc[0])

    # Top KPI Metrics Row
    kpi1, kpi2, kpi3, kpi4, kpi5 = st.columns(5)
    kpi1.metric("Current Balance", f"₹{latest_bal:,.0f}")
    kpi2.metric("Total Income", f"₹{total_income:,.0f}")
    kpi3.metric("Total Expenses", f"₹{total_expenses:,.0f}")
    kpi4.metric("Net Savings", f"₹{net_savings:,.0f}", delta=f"{savings_rate:.1f}% rate")
    kpi5.metric("Safe-to-Spend", f"₹{safe_amount:,.0f}", delta=f"₹{daily_safe:,.0f}/day")

    st.markdown("---")

    # Row 1: Spending by Category & Monthly Trend
    col_cat, col_trend = st.columns([1.1, 1.2])

    with col_cat:
        st.subheader("🛒 Spending by Category")
        if not expense_sub.empty:
            cat_totals = expense_sub.groupby("category")["amount"].sum().sort_values(ascending=True).reset_index()
            fig_cat = px.bar(
                cat_totals,
                x="amount",
                y="category",
                orientation="h",
                text="amount",
                labels={"amount": "Total Spent (₹)", "category": "Category"},
                color="amount",
                color_continuous_scale="Teal"
            )
            fig_cat.update_traces(texttemplate="₹%{text:,.0f}", textposition="outside")
            fig_cat.update_layout(height=380, margin=dict(l=10, r=20, t=20, b=20), coloraxis_showscale=False)
            st.plotly_chart(fig_cat, use_container_width=True)
        else:
            st.info("No expense records found matching current filters.")

    with col_trend:
        st.subheader("📅 Monthly Spending & Income Trend")
        if not filtered_df.empty:
            temp_df = filtered_df.copy()
            temp_df["month"] = temp_df["date"].dt.to_period("M").astype(str)
            m_summary = temp_df.groupby(["month", "transaction_type"])["amount"].sum().reset_index()

            fig_trend = px.bar(
                m_summary,
                x="month",
                y="amount",
                color="transaction_type",
                barmode="group",
                labels={"amount": "Amount (₹)", "month": "Month", "transaction_type": "Type"},
                color_discrete_map={"Debit": "#ef4444", "Credit": "#22c55e"}
            )
            fig_trend.update_layout(height=380, margin=dict(l=10, r=20, t=20, b=20), legend=dict(orientation="h", y=1.1))
            st.plotly_chart(fig_trend, use_container_width=True)
        else:
            st.info("No records available.")

    st.markdown("---")

    # Row 2: Cashflow Split, Payment Modes, and Recurring Bills
    col_pie1, col_pie2, col_rec = st.columns(3)

    with col_pie1:
        st.subheader("💳 Cashflow Breakdown")
        cf_df = pd.DataFrame({
            "Type": ["Expenses (Debit)", "Income (Credit)"],
            "Amount": [total_expenses, total_income]
        })
        fig_cf = px.pie(
            cf_df,
            names="Type",
            values="Amount",
            hole=0.55,
            color="Type",
            color_discrete_map={"Expenses (Debit)": "#f87171", "Income (Credit)": "#4ade80"}
        )
        fig_cf.update_traces(textinfo="percent+label", hovertemplate="₹%{value:,.0f}")
        fig_cf.update_layout(height=320, margin=dict(l=10, r=10, t=20, b=10), showlegend=False)
        st.plotly_chart(fig_cf, use_container_width=True)

    with col_pie2:
        st.subheader("📱 Payment Mode Distribution")
        if "payment_mode" in expense_sub.columns and not expense_sub.empty:
            pm_data = expense_sub.groupby("payment_mode")["amount"].sum().reset_index()
            fig_pm = px.pie(
                pm_data,
                names="payment_mode",
                values="amount",
                hole=0.45,
                color_discrete_sequence=px.colors.qualitative.Prism
            )
            fig_pm.update_traces(textinfo="percent+label", hovertemplate="₹%{value:,.0f}")
            fig_pm.update_layout(height=320, margin=dict(l=10, r=10, t=20, b=10), showlegend=False)
            st.plotly_chart(fig_pm, use_container_width=True)
        else:
            st.info("Payment mode data unavailable.")

    with col_rec:
        st.subheader("🔄 Recurring vs One-time")
        if "is_recurring" in expense_sub.columns and not expense_sub.empty:
            rec_df = expense_sub.groupby("is_recurring")["amount"].sum().reset_index()
            rec_df["Label"] = rec_df["is_recurring"].map({True: "Recurring Mandates", False: "One-Time Expenses"})
            fig_rec = px.pie(
                rec_df,
                names="Label",
                values="amount",
                hole=0.5,
                color_discrete_sequence=["#38bdf8", "#fbbf24"]
            )
            fig_rec.update_traces(textinfo="percent+label", hovertemplate="₹%{value:,.0f}")
            fig_rec.update_layout(height=320, margin=dict(l=10, r=10, t=20, b=10), showlegend=False)
            st.plotly_chart(fig_rec, use_container_width=True)
        else:
            st.info("Recurring flag data not available.")

    st.markdown("---")

    # Row 3: Top Merchants & Recent Transactions
    col_merch, col_recent = st.columns([1, 1.3])

    with col_merch:
        st.subheader("🏪 Top 10 Merchants by Spend")
        if "merchant" in expense_sub.columns and not expense_sub.empty:
            top_merch = expense_sub.groupby("merchant")["amount"].sum().nlargest(10).reset_index()
            fig_merch = px.bar(
                top_merch.sort_values("amount", ascending=True),
                x="amount",
                y="merchant",
                orientation="h",
                text="amount",
                color="amount",
                color_continuous_scale="Purp"
            )
            fig_merch.update_traces(texttemplate="₹%{text:,.0f}", textposition="outside")
            fig_merch.update_layout(height=380, margin=dict(l=10, r=20, t=10, b=10), coloraxis_showscale=False)
            st.plotly_chart(fig_merch, use_container_width=True)
        else:
            st.info("Merchant data unavailable.")

    with col_recent:
        st.subheader("🧾 Recent Transactions")
        sort_cols = ["date"]
        if "time" in filtered_df.columns:
            sort_cols.append("time")
        recent_df = filtered_df.sort_values(sort_cols, ascending=False).head(12)

        show_cols = ["date", "amount", "transaction_type", "category", "merchant", "payment_mode"]
        actual_cols = [c for c in show_cols if c in recent_df.columns]
        display_recent = recent_df[actual_cols].copy()
        display_recent["amount"] = display_recent["amount"].apply(lambda x: f"₹{x:,.2f}")

        st.dataframe(display_recent, width="stretch", hide_index=True, height=360)


# ------------------------------------------------------------------------------
# MODULE 2: 🤖 ML SPENDING PREDICTION & MULTI-MONTH FORECASTING
# ------------------------------------------------------------------------------
elif selected_menu == "🤖 ML Spending Prediction":
    st.markdown("## 🤖 Machine Learning Spending Prediction & Forecasting")
    st.markdown(
        '<div class="section-note">'
        'Predict future monthly spending, model expenditure trajectories, and evaluate regression metrics (MAE, RMSE, R²).'
        '</div>',
        unsafe_allow_html=True
    )

    monthly_spending_series = ml_models.prepare_monthly_spending_series(working_df)

    if len(monthly_spending_series) < 3:
        st.warning("⚠️ Insufficient monthly history for training predictive models. At least 3 distinct calendar months required.")
    else:
        # Train models
        trained_info = ml_models.train_spending_models(monthly_spending_series)

        col_ctrl1, col_ctrl2 = st.columns(2)
        with col_ctrl1:
            forecast_horizon = st.slider("Forecast Horizon (Months Ahead)", min_value=1, max_value=12, value=4)
        with col_ctrl2:
            model_selected = st.selectbox(
                "Prediction Algorithm",
                ["Linear Regression", "Random Forest"],
                index=0,
                help="Linear Regression excels at directional trends, while Random Forest handles non-linear holiday surges."
            )

        # Generate Future Forecast
        forecast_df = ml_models.forecast_future_spending(
            monthly_spending_series, trained_info, horizon_months=forecast_horizon, model_choice=model_selected
        )

        # Chart: Historical Spending + Forecast Trajectory
        st.subheader(f"📈 Spending Forecast ({model_selected})")

        hist_plot_df = monthly_spending_series[["month", "monthly_spending"]].copy()
        hist_plot_df.columns = ["Month", "Spending (₹)"]
        hist_plot_df["Type"] = "Historical Actual"

        fc_plot_df = forecast_df[["Month", "Forecasted Spending (₹)"]].copy()
        fc_plot_df.columns = ["Month", "Spending (₹)"]
        fc_plot_df["Type"] = f"{model_selected} Forecast"

